import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 법정 기준시간은 주 40시간 (근태 설정값 테이블이 스키마에 없다)
const LEGAL_WEEK_HOURS = 40;
// 가정: 업로드 파일은 첫 줄이 아래 머리글인 쉼표 구분 텍스트(CSV)다
const UPLOAD_HEADER = 'employeeId,workDate,clockInAt,clockOutAt';
const DATE_RE = /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/;
const TS_RE = /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])[T ][0-2][0-9]:[0-5][0-9](:[0-5][0-9])?(Z|[+-][0-9]{2}:?[0-9]{2})?$/;
const ID_RE = /^[0-9]{1,18}$/;

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function optText(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v).trim();
}

function pageOf(q: Record<string, unknown>): { page: number; size: number } {
  const rawPage = optText(q['page']);
  const rawSize = optText(q['size']);
  const page = rawPage === null ? 0 : Number(rawPage);
  const size = rawSize === null ? 20 : Number(rawSize);
  if (!Number.isInteger(page) || page < 0) {
    throw invalid('page는 0 이상의 정수여야 합니다.');
  }
  if (!Number.isInteger(size) || size < 1 || size > 200) {
    throw invalid('size는 1~200 사이의 정수여야 합니다.');
  }
  return { page, size };
}

function rangeOf(q: Record<string, unknown>): { startDate: string | null; endDate: string | null } {
  const startDate = optText(q['startDate']);
  const endDate = optText(q['endDate']);
  if (startDate !== null && !DATE_RE.test(startDate)) {
    throw invalid('조회 시작일 형식이 올바르지 않습니다.');
  }
  if (endDate !== null && !DATE_RE.test(endDate)) {
    throw invalid('조회 종료일 형식이 올바르지 않습니다.');
  }
  return { startDate, endDate };
}

async function employeeExists(db: Db, employeeId: string): Promise<boolean> {
  const rows = await db.query(
    'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
    { employeeId },
  );
  return rows.length > 0;
}

async function orderOk(db: Db, clockInAt: string | null, clockOutAt: string | null): Promise<boolean> {
  if (clockInAt === null || clockOutAt === null) {
    return true;
  }
  const rows = await db.query(
    'SELECT (CAST(:clockOutAt AS timestamptz) >= CAST(:clockInAt AS timestamptz)) AS "ok"',
    { clockInAt, clockOutAt },
  );
  return rows[0]['ok'] === true;
}

// 마감된 근태는 반영하지 않는다 (공통 P11은 공통 모듈 몫이지만 API 표의 409를 여기서 낸다)
async function saveDaily(
  db: Db,
  employeeId: string,
  workDate: string,
  clockInAt: string | null,
  clockOutAt: string | null,
  sourceType: string,
): Promise<number> {
  const old = await db.query(
    'SELECT attendance_daily_id AS "attendanceDailyId", closing_status AS "closingStatus" FROM attendance_daily WHERE employee_id = CAST(:employeeId AS bigint) AND work_date = CAST(:workDate AS date)',
    { employeeId, workDate },
  );
  if (old.length > 0) {
    if (old[0]['closingStatus'] === '마감') {
      throw new ApiError(409, 'ATTENDANCE_CLOSED', '마감된 근태입니다. 마감취소 후 반영할 수 있습니다.');
    }
    const updated = await db.query(
      'UPDATE attendance_daily SET clock_in_at = CAST(:clockInAt AS timestamptz), clock_out_at = CAST(:clockOutAt AS timestamptz), source_type = :sourceType, updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId"',
      { clockInAt, clockOutAt, sourceType, id: String(old[0]['attendanceDailyId']) },
    );
    return Number(updated[0]['attendanceDailyId']);
  }
  const inserted = await db.query(
    'INSERT INTO attendance_daily (employee_id, work_date, clock_in_at, clock_out_at, source_type, closing_status, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), CAST(:workDate AS date), CAST(:clockInAt AS timestamptz), CAST(:clockOutAt AS timestamptz), :sourceType, :closingStatus, now(), now()) RETURNING attendance_daily_id AS "attendanceDailyId"',
    { employeeId, workDate, clockInAt, clockOutAt, sourceType, closingStatus: '신청' },
  );
  return Number(inserted[0]['attendanceDailyId']);
}

@Controller('api/v1')
export class FnSfr01809Controller {
  @Post('/attendance-dailies/upload')
  @HttpCode(200)
  async uploadAttendanceDailies(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const file = optText(data['file']);
    if (file === null) {
      throw invalid('출퇴근 정보 엑셀 파일은 필수입니다.');
    }
    const lines = String(data['file']).split(/[\r\n]+/);
    const numbered: { no: number; text: string }[] = [];
    lines.forEach((text, i) => {
      if (text.trim() !== '') {
        numbered.push({ no: i + 1, text: text.trim() });
      }
    });
    if (numbered.length === 0 || numbered[0].text.replace(/ /g, '') !== UPLOAD_HEADER) {
      throw new ApiError(422, 'INVALID_UPLOAD_FORMAT', '파일 양식이 올바르지 않습니다. 머리글은 ' + UPLOAD_HEADER + ' 이어야 합니다.');
    }
    return transaction(async (db) => {
      const errorRows: { row: number; reason: string }[] = [];
      let successCount = 0;
      for (const line of numbered.slice(1)) {
        const cols = line.text.split(',').map((c) => c.trim());
        if (cols.length !== 4) {
          errorRows.push({ row: line.no, reason: '열 개수가 올바르지 않습니다.' });
          continue;
        }
        const employeeId = cols[0];
        const workDate = cols[1];
        const clockInAt = cols[2] === '' ? null : cols[2];
        const clockOutAt = cols[3] === '' ? null : cols[3];
        if (!ID_RE.test(employeeId)) {
          errorRows.push({ row: line.no, reason: '임직원 ID 형식이 올바르지 않습니다.' });
          continue;
        }
        if (!DATE_RE.test(workDate)) {
          errorRows.push({ row: line.no, reason: '근무일자 형식이 올바르지 않습니다.' });
          continue;
        }
        if ((clockInAt !== null && !TS_RE.test(clockInAt)) || (clockOutAt !== null && !TS_RE.test(clockOutAt))) {
          errorRows.push({ row: line.no, reason: '출퇴근 시각 형식이 올바르지 않습니다.' });
          continue;
        }
        if (!(await employeeExists(db, employeeId))) {
          errorRows.push({ row: line.no, reason: '임직원이 없습니다.' });
          continue;
        }
        if (!(await orderOk(db, clockInAt, clockOutAt))) {
          errorRows.push({ row: line.no, reason: '퇴근시각이 출근시각보다 빠릅니다.' });
          continue;
        }
        await saveDaily(db, employeeId, workDate, clockInAt, clockOutAt, 'UPLOAD');
        successCount += 1;
      }
      return { successCount, errorRows };
    });
  }

  @Post('/attendance-dailies/interface')
  @HttpCode(200)
  async receiveAttendanceInterface(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const employeeId = optText(data['employeeId']);
    const workDate = optText(data['workDate']);
    const clockInAt = optText(data['clockInAt']);
    const clockOutAt = optText(data['clockOutAt']);
    if (employeeId === null || !ID_RE.test(employeeId)) {
      throw invalid('임직원은 필수이며 정수여야 합니다.');
    }
    if (workDate === null || !DATE_RE.test(workDate)) {
      throw invalid('근무일자는 필수이며 YYYY-MM-DD 형식이어야 합니다.');
    }
    if ((clockInAt !== null && !TS_RE.test(clockInAt)) || (clockOutAt !== null && !TS_RE.test(clockOutAt))) {
      throw invalid('출퇴근 시각 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      if (!(await employeeExists(db, employeeId))) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      if (!(await orderOk(db, clockInAt, clockOutAt))) {
        throw invalid('퇴근시각은 출근시각 이후여야 합니다.');
      }
      const attendanceDailyId = await saveDaily(db, employeeId, workDate, clockInAt, clockOutAt, 'INTERFACE');
      return { attendanceDailyId };
    });
  }

  @Get('/attendance-dailies/weekly-summaries')
  async listWeeklyWorkSummaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자', '시스템 관리자');
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    const { startDate, endDate } = rangeOf(q);
    return transaction(async (db) => {
      const base =
        "SELECT employee_id, date_trunc('week', work_date) AS week_start, SUM(EXTRACT(EPOCH FROM (clock_out_at - clock_in_at))) / 3600 AS hours FROM attendance_daily WHERE clock_in_at IS NOT NULL AND clock_out_at IS NOT NULL AND (CAST(:startDate AS date) IS NULL OR work_date >= CAST(:startDate AS date)) AND (CAST(:endDate AS date) IS NULL OR work_date <= CAST(:endDate AS date)) GROUP BY employee_id, date_trunc('week', work_date)";
      const items = await db.query(
        'SELECT employee_id AS "employeeId", CAST(week_start AS date) AS "weekStart", CAST(ROUND(CAST(hours AS numeric), 2) AS numeric) AS "weekWorkHours", (hours > CAST(:legalHours AS numeric)) AS "exceeded" FROM (' +
          base +
          ') w ORDER BY week_start DESC, employee_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { startDate, endDate, legalHours: LEGAL_WEEK_HOURS, size, offset: page * size },
      );
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM (' + base + ') w', { startDate, endDate });
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Get('/attendance-dailies/type-summaries')
  async listAttendanceTypeSummaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자', '시스템 관리자');
    const q = checks.queryOf(req.query);
    const { page, size } = pageOf(q);
    const { startDate, endDate } = rangeOf(q);
    return transaction(async (db) => {
      const where =
        'FROM attendance_request WHERE (CAST(:startDate AS date) IS NULL OR end_date >= CAST(:startDate AS date)) AND (CAST(:endDate AS date) IS NULL OR start_date <= CAST(:endDate AS date))';
      const items = await db.query(
        'SELECT attendance_type_id AS "attendanceTypeId", COUNT(*) AS "count" ' +
          where +
          ' GROUP BY attendance_type_id ORDER BY attendance_type_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { startDate, endDate, size, offset: page * size },
      );
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM (SELECT attendance_type_id ' + where + ' GROUP BY attendance_type_id) t',
        { startDate, endDate },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }
}

