import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  Badge,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  Num,
  Pager,
  RefName,
  Tiles,
  TextInput,
  LookupSelect,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr01809Page({ role, notify }: PageProps) {
  const today = new Date().toISOString().slice(0, 10);
  const monthStart = today.slice(0, 8) + '01';
  const [startDate, setStartDate] = useState<string>(monthStart);
  const [endDate, setEndDate] = useState<string>(today);
  const [applied, setApplied] = useState<Row>({ startDate: monthStart, endDate: today });
  const [page, setPage] = useState(0);
  const [weeklyPage, setWeeklyPage] = useState(0);
  const [drawer, setDrawer] = useState<'upload' | 'interface' | null>(null);

  const [file, setFile] = useState('');
  const [uploadErrors, setUploadErrors] = useState<Row[] | null>(null);

  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [workDate, setWorkDate] = useState('');
  const [clockInAt, setClockInAt] = useState('');
  const [clockOutAt, setClockOutAt] = useState('');

  const daily = useData<Page>(
    () => call<Page>('GET', '/attendance-dailies', role, undefined, { ...applied, page, size: 20 }),
    [applied, page],
  );
  const weekly = useData<Page>(
    () => call<Page>('GET', '/attendance-dailies/weekly-summaries', role, undefined, { ...applied, page: weeklyPage, size: 20 }),
    [applied, weeklyPage],
  );
  const types = useData<Page>(
    () => call<Page>('GET', '/attendance-dailies/type-summaries', role, undefined, { ...applied, page: 0, size: 200 }),
    [applied],
  );

  const exceededRows = (weekly.data?.items ?? []).filter((r) => r['exceeded'] === true);

  function search() {
    if (!startDate || !endDate) {
      notify('조회 시작일과 종료일을 입력하세요.');
      return;
    }
    setPage(0);
    setWeeklyPage(0);
    setApplied({ startDate, endDate });
  }

  function reset() {
    setStartDate(monthStart);
    setEndDate(today);
    setPage(0);
    setWeeklyPage(0);
    setApplied({ startDate: monthStart, endDate: today });
  }

  function reloadAll() {
    daily.reload();
    weekly.reload();
    types.reload();
  }

  async function upload() {
    if (!file.trim()) {
      throw new Error('출퇴근 정보 파일 내용을 입력하세요.');
    }
    const res = await call<Row>('POST', '/attendance-dailies/upload', role, { file });
    const errors = (res['errorRows'] as Row[] | undefined) ?? [];
    setUploadErrors(errors);
    notify('업로드를 반영했습니다. 반영 ' + String(res['successCount']) + '건, 오류 ' + errors.length + '건');
    reloadAll();
  }

  async function receive() {
    if (employeeId === '' || !workDate) {
      throw new Error('임직원과 근무일자는 필수입니다.');
    }
    await call<Row>('POST', '/attendance-dailies/interface', role, {
      employeeId,
      workDate,
      clockInAt: clockInAt || undefined,
      clockOutAt: clockOutAt || undefined,
    });
    notify('출퇴근 기록을 수신했습니다.');
    setDrawer(null);
    reloadAll();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>근무 현황</h2>
        <Tiles
          items={[
            ['근무시간 기록', <Num value={daily.data?.total ?? 0} />],
            ['초과 근무자(현재 쪽)', <Num value={exceededRows.length} />],
            ['근태 유형 수', <Num value={types.data?.total ?? 0} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>근무시간 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        <Band total={daily.data?.total}>
          <button type="button" onClick={() => { setUploadErrors(null); setFile(''); setDrawer('upload'); }}>엑셀 업로드</button>
          <button type="button" onClick={() => { setEmployeeId(''); setWorkDate(''); setClockInAt(''); setClockOutAt(''); setDrawer('interface'); }}>출퇴근 기록 수신</button>
        </Band>
        {daily.error ? <ErrorText text={daily.error} /> : null}
        <DataTable
          rows={daily.data?.items ?? []}
          empty="조회된 근무시간이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r['workDate']} /> },
            { key: 'clockInAt', label: '출근시각', render: (r) => <DateText value={r['clockInAt']} time /> },
            { key: 'clockOutAt', label: '퇴근시각', render: (r) => <DateText value={r['clockOutAt']} time /> },
            { key: 'sourceType', label: '기록 출처' },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
          ]}
        />
        <Pager page={page} size={20} total={daily.data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>초과 근무자</h2>
        <DataTable
          rows={exceededRows}
          empty="기준시간 초과자가 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'weekWorkHours', label: '주 근무시간', render: (r) => <Num value={r['weekWorkHours']} /> },
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>주 근무시간 집계</h2>
        {weekly.error ? <ErrorText text={weekly.error} /> : null}
        <DataTable
          rows={weekly.data?.items ?? []}
          empty="집계 결과가 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'weekStart', label: '주 시작일', render: (r) => <DateText value={r['weekStart']} /> },
            { key: 'weekWorkHours', label: '주 근무시간', render: (r) => <Num value={r['weekWorkHours']} /> },
            { key: 'exceeded', label: '법정 기준시간 초과 여부', render: (r) => <Badge value={r['exceeded'] === true ? '초과' : '정상'} /> },
          ]}
        />
        <Pager page={weeklyPage} size={20} total={weekly.data?.total ?? 0} onPage={setWeeklyPage} />
      </section>

      <section className="box span-4">
        <h2>근태 유형별 건수</h2>
        {types.error ? <ErrorText text={types.error} /> : null}
        <DataTable
          rows={types.data?.items ?? []}
          empty="집계 결과가 없습니다."
          columns={[
            { key: 'attendanceTypeId', label: '근태항목', render: (r) => <RefName table="attendance_type" role={role} value={r['attendanceTypeId']} /> },
            { key: 'count', label: '유형별 건수', render: (r) => <Num value={r['count']} /> },
          ]}
        />
      </section>

      {drawer === 'upload' ? (
        <Drawer title="출퇴근 정보 엑셀 업로드" onClose={() => setDrawer(null)}>
          <Form
            submit="업로드"
            onSubmit={upload}
            note={
              uploadErrors ? (
                <DataTable
                  rows={uploadErrors}
                  empty="오류 행이 없습니다."
                  columns={[
                    { key: 'row', label: '오류 행 번호' },
                    { key: 'reason', label: '사유' },
                  ]}
                />
              ) : undefined
            }
          >
            <Field label="출퇴근 정보 엑셀 파일" required wide hint="첫 줄: employeeId,workDate,clockInAt,clockOutAt">
              <TextInput value={file} onChange={setFile} multiline placeholder="엑셀 내용을 쉼표 구분 텍스트로 붙여 넣으세요" />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {drawer === 'interface' ? (
        <Drawer title="출퇴근 기록 수신" onClose={() => setDrawer(null)}>
          <Form submit="수신" onSubmit={receive}>
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label="근무일자" required>
              <DateInput value={workDate} onChange={setWorkDate} />
            </Field>
            <Field label="출근시각" hint="예: 2024-05-02T09:00:00+09:00">
              <TextInput value={clockInAt} onChange={setClockInAt} />
            </Field>
            <Field label="퇴근시각" hint="예: 2024-05-02T18:00:00+09:00">
              <TextInput value={clockOutAt} onChange={setClockOutAt} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
